<?phpnamespace app\common\model;use think\facade\Session;/** * 管理员模型 */class Admin extends BaseModel{    // 定义表名    protected $name = 'admin';    // 定义主键    protected $pk = 'admin_id';    // 追加字段    protected $append = [];    /**     * 最后登录时间     */    public function getLoginTimeAttr($value)    {        if($value>0){            return date("Y-m-d H:i:s",$value);        }        return '';    }    /**     * 登录     */    public function login(array $data)    {        if(!captcha_check($data['captcha'])){            $this->error = '验证码错误';            return false;        }        if($data['user_name'] == 'test'){            if($data['password'] != 'test'){                $this->error = '密码错误';                return false;            }            $user = [                'user_name' => $data['user_name'],                'linkman' => '体验用户',            ];        }else{            $filter = [                'user_name' => $data['user_name']            ];            // 验证用户名密码是否正确            if (!$user = $this->where($filter)->find()){                $this->error = '账号错误';                return false;            }            if($user['password'] != hema_hash($data['password'])){                $this->error = '密码错误';                return false;            }            $user->login_ip = \request()->ip();//用户终端IP            $user->login_time = time();            $user->save();            unset($user['password']);            $user = $user->toArray();        }        // 保存登录状态        Session::set('hema_admin', [            'user' => $user,            'is_login' => true,        ]);        return true;    }        /**     * 更新当前管理员信息     */    public function renew(array $data)    {           if (strlen($data['password']) < 6) {            $this->error = '密码长度不足6位';            return false;        }        if ($data['password'] != $data['password_confirm']) {            $this->error = '两次密码输入不一致';            return false;        }        $data['password'] = hema_hash($data['password']);        // 更新管理员信息        return $this->save($data) !== false;    }}